30	class TooltipRichContent {
31	
32	    private _zr: ZRenderType;
33	
34	    private _show = false;
35	
36	    private _styleCoord: [number, number, number, number] = [0, 0, 0, 0];
37	
38	    private _hideTimeout: number;
39	
40	    private _alwaysShowContent: boolean = false;
41	
42	    private _enterable = true;
43	
44	    private _inContent: boolean;
45	
46	    private _hideDelay: number;
47	
48	    el: ZRText;
49	
50	    constructor(api: ExtensionAPI) {
51	        this._zr = api.getZr();
52	        makeStyleCoord(this._styleCoord, this._zr, api.getWidth() / 2, api.getHeight() / 2);
53	    }
54	
55	    /**
56	     * Update when tooltip is rendered
57	     */
58	    update(tooltipModel: Model<TooltipOption>) {
59	        const alwaysShowContent = tooltipModel.get('alwaysShowContent');
60	        alwaysShowContent && this._moveIfResized();
61	
62	        // update alwaysShowContent
63	        this._alwaysShowContent = alwaysShowContent;
64	    }
65	
66	    show() {
67	        if (this._hideTimeout) {
68	            clearTimeout(this._hideTimeout);
69	        }
70	
71	        this.el.show();
72	        this._show = true;
73	    }
74	
75	    /**
76	     * Set tooltip content
77	     */
78	    setContent(
79	        content: string | HTMLElement | HTMLElement[],
80	        markupStyleCreator: TooltipMarkupStyleCreator,
81	        tooltipModel: Model<TooltipOption>,
82	        borderColor: ZRColor,
83	        arrowPosition: TooltipOption['position']
84	    ) {
85	        if (zrUtil.isObject(content)) {
86	            throwError(__DEV__ ? 'Passing DOM nodes as content is not supported in richText tooltip!' : '');
87	        }
88	        if (this.el) {
89	            this._zr.remove(this.el);
90	        }
91	
92	        const textStyleModel = tooltipModel.getModel('textStyle');
93	
94	        this.el = new ZRText({
95	            style: {
96	                rich: markupStyleCreator.richTextStyles,
97	                text: content as string,
98	                lineHeight: 22,
99	                borderWidth: 1,
100	                borderColor: borderColor as string,
101	                textShadowColor: textStyleModel.get('textShadowColor'),
102	                fill: tooltipModel.get(['textStyle', 'color']),
103	                padding: getPaddingFromTooltipModel(tooltipModel, 'richText'),
104	                verticalAlign: 'top',
105	                align: 'left'
106	            },
107	            z: tooltipModel.get('z')
108	        });
109	        zrUtil.each([
110	            'backgroundColor', 'borderRadius', 'shadowColor', 'shadowBlur', 'shadowOffsetX', 'shadowOffsetY'
111	        ] as const, propName => {
112	            (this.el.style as any)[propName] = tooltipModel.get(propName);
113	        });
114	        zrUtil.each([
115	            'textShadowBlur', 'textShadowOffsetX', 'textShadowOffsetY'
116	        ] as const, propName => {
117	            this.el.style[propName] = textStyleModel.get(propName) || 0;
118	        });
119	
120	        this._zr.add(this.el);
121	
122	        const self = this;
123	        this.el.on('mouseover', function () {
124	            // clear the timeout in hideLater and keep showing tooltip
125	            if (self._enterable) {
126	                clearTimeout(self._hideTimeout);
127	                self._show = true;
128	            }
129	            self._inContent = true;
130	        });
131	        this.el.on('mouseout', function () {
132	            if (self._enterable) {
133	                if (self._show) {
134	                    self.hideLater(self._hideDelay);
135	                }
136	            }
137	            self._inContent = false;
138	        });
139	    }
140	
141	    setEnterable(enterable?: boolean) {
142	        this._enterable = enterable;
143	    }
144	
145	    getSize() {
146	        const el = this.el;
147	        const bounding = this.el.getBoundingRect();
148	        // bounding rect does not include shadow. For renderMode richText,
149	        // if overflow, it will be cut. So calculate them accurately.
150	        const shadowOuterSize = calcShadowOuterSize(el.style);
151	        return [
152	            bounding.width + shadowOuterSize.left + shadowOuterSize.right,
153	            bounding.height + shadowOuterSize.top + shadowOuterSize.bottom
154	        ];
155	    }
156	
157	    moveTo(x: number, y: number) {
158	        const el = this.el;
159	        if (el) {
160	            const styleCoord = this._styleCoord;
161	            makeStyleCoord(styleCoord, this._zr, x, y);
162	            x = styleCoord[0];
163	            y = styleCoord[1];
164	            const style = el.style;
165	            const borderWidth = mathMaxWith0(style.borderWidth || 0);
166	            const shadowOuterSize = calcShadowOuterSize(style);
167	            // rich text x, y do not include border.
168	            el.x = x + borderWidth + shadowOuterSize.left;
169	            el.y = y + borderWidth + shadowOuterSize.top;
170	            el.markRedraw();
171	        }
172	    }
173	
174	
175	    /**
176	     * when `alwaysShowContent` is true,
177	     * move the tooltip after chart resized
178	     */
179	    _moveIfResized() {
180	        // The ratio of left to width
181	        const ratioX = this._styleCoord[2];
182	        // The ratio of top to height
183	        const ratioY = this._styleCoord[3];
184	        this.moveTo(
185	            ratioX * this._zr.getWidth(),
186	            ratioY * this._zr.getHeight()
187	        );
188	    }
189	
190	    hide() {
191	        if (this.el) {
192	            this.el.hide();
193	        }
194	        this._show = false;
195	    }
196	
197	    hideLater(time?: number) {
198	        if (this._show && !(this._inContent && this._enterable) && !this._alwaysShowContent) {
199	            if (time) {
200	                this._hideDelay = time;
201	                // Set show false to avoid invoke hideLater multiple times
202	                this._show = false;
203	                this._hideTimeout = setTimeout(zrUtil.bind(this.hide, this), time) as any;
204	            }
205	            else {
206	                this.hide();
207	            }
208	        }
209	    }
210	
211	    isShow() {
212	        return this._show;
213	    }
214	
215	    dispose() {
216	        this._zr.remove(this.el);
217	    }
218	}
219	
220	function mathMaxWith0(val: number): number {
221	    return Math.max(0, val);
222	}
223	
224	function calcShadowOuterSize(style: TextStyleProps) {
225	    const shadowBlur = mathMaxWith0(style.shadowBlur || 0);
226	    const shadowOffsetX = mathMaxWith0(style.shadowOffsetX || 0);
227	    const shadowOffsetY = mathMaxWith0(style.shadowOffsetY || 0);
228	    return {
229	        left: mathMaxWith0(shadowBlur - shadowOffsetX),
230	        right: mathMaxWith0(shadowBlur + shadowOffsetX),
231	        top: mathMaxWith0(shadowBlur - shadowOffsetY),
232	        bottom: mathMaxWith0(shadowBlur + shadowOffsetY)
233	    };
234	}
235	
236	function makeStyleCoord(out: number[], zr: ZRenderType, zrX: number, zrY: number) {
237	    out[0] = zrX;
238	    out[1] = zrY;
239	    out[2] = out[0] / zr.getWidth();
240	    out[3] = out[1] / zr.getHeight();
241	}
242	
243	export default TooltipRichContent;
