28	type DispatchActionMethod = ExtensionAPI['dispatchAction'];
29	
30	type Handler = (
31	    currTrigger: 'click' | 'mousemove' | 'leave',
32	    event: ZRElementEvent,
33	    dispatchAction: DispatchActionMethod
