40	interface InnerStore {
41	    initialized: boolean
42	    records: Dictionary<Record>
43	}
44	
45	interface ShowTipPayload {
46	    type: 'showTip'
47	    dispatchAction: DispatchActionMethod
48	}
49	
50	interface HideTipPayload {
51	    type: 'hideTip'
52	    dispatchAction: DispatchActionMethod
53	}
54	interface Pendings {
55	    showTip: ShowTipPayload[]
56	    hideTip: HideTipPayload[]
57	}
58	
59	const inner = makeInner<InnerStore, ZRenderType>();
60	const each = zrUtil.each;
61	
62	/**
63	 * @param {string} key
64	 * @param {module:echarts/ExtensionAPI} api
65	 * @param {Function} handler
66	 *      param: {string} currTrigger
67	 *      param: {Array.<number>} point
68	 */
69	export function register(key: string, api: ExtensionAPI, handler?: Handler) {
70	    if (env.node) {
71	        return;
72	    }
73	
74	    const zr = api.getZr();
75	    inner(zr).records || (inner(zr).records = {});
76	
77	    initGlobalListeners(zr, api);
78	
79	    const record = inner(zr).records[key] || (inner(zr).records[key] = {} as Record);
80	    record.handler = handler;
81	}
82	
83	function initGlobalListeners(zr: ZRenderType, api?: ExtensionAPI) {
84	    if (inner(zr).initialized) {
85	        return;
86	    }
87	
88	    inner(zr).initialized = true;
89	
90	    useHandler('click', zrUtil.curry(doEnter, 'click'));
91	    useHandler('mousemove', zrUtil.curry(doEnter, 'mousemove'));
92	    // useHandler('mouseout', onLeave);
93	    useHandler('globalout', onLeave);
94	
95	    function useHandler(
96	        eventType: string,
97	        cb: (record: Record, e: ZRElementEvent, dispatchAction: DispatchActionMethod) => void
98	    ) {
99	        zr.on(eventType, function (e: ZRElementEvent) {
100	            const dis = makeDispatchAction(api);
101	
102	            each(inner(zr).records, function (record) {
103	                record && cb(record, e, dis.dispatchAction);
104	            });
105	
106	            dispatchTooltipFinally(dis.pendings, api);
107	        });
108	    }
109	}
110	
111	function dispatchTooltipFinally(pendings: Pendings, api: ExtensionAPI) {
112	    const showLen = pendings.showTip.length;
113	    const hideLen = pendings.hideTip.length;
114	
115	    let actuallyPayload;
116	    if (showLen) {
117	        actuallyPayload = pendings.showTip[showLen - 1];
118	    }
119	    else if (hideLen) {
120	        actuallyPayload = pendings.hideTip[hideLen - 1];
121	    }
122	    if (actuallyPayload) {
123	        actuallyPayload.dispatchAction = null;
124	        api.dispatchAction(actuallyPayload);
125	    }
126	}
127	
128	function onLeave(
129	    record: Record,
130	    e: ZRElementEvent,
131	    dispatchAction: DispatchActionMethod
132	) {
133	    record.handler('leave', null, dispatchAction);
134	}
135	
136	function doEnter(
137	    currTrigger: 'click' | 'mousemove' | 'leave',
138	    record: Record,
139	    e: ZRElementEvent,
140	    dispatchAction: DispatchActionMethod
141	) {
142	    record.handler(currTrigger, e, dispatchAction);
143	}
144	
145	function makeDispatchAction(api: ExtensionAPI) {
146	    const pendings: Pendings = {
147	        showTip: [],
148	        hideTip: []
149	    };
150	    // FIXME
151	    // better approach?
152	    // 'showTip' and 'hideTip' can be triggered by axisPointer and tooltip,
153	    // which may be conflict, (axisPointer call showTip but tooltip call hideTip);
154	    // So we have to add "final stage" to merge those dispatched actions.
155	    const dispatchAction = function (payload: ShowTipPayload | HideTipPayload) {
156	        const pendingList = pendings[payload.type];
157	        if (pendingList) {
158	            (pendingList as ShowTipPayload[]).push(payload as ShowTipPayload);
159	        }
160	        else {
161	            payload.dispatchAction = dispatchAction;
162	            api.dispatchAction(payload);
163	        }
164	    };
165	
166	    return {
167	        dispatchAction: dispatchAction,
168	        pendings: pendings
169	    };
170	}
